    public function testAuthorizationCodeGrantReturnsTokenSet(): void
    {
        $clientData = $this->clientStore->preValidatedClient(self::CLIENT_ID);
        $authResult = new AuthenticationResult(
            valid: true,
            id: self::USER_ID,
            tenant: self::TENANT,
            tenantName: self::TENANT,
            scope: 'openid profile email',
            name: 'Test User',
            email: 'test@example.com',
            roles: ['user'],
            groups: [],
        );
        $authRequest = new AuthenticationRequest($clientData, 'openid profile email', 'https://app.example.com/callback');
        $code = new TemporalAuthCode(
            data: $authResult,
            client: $clientData,
            nonce: 'test-nonce-123',
            request: $authRequest,
            sessionId: self::SESSION_ID,
        );
        $codeKey = $this->temporalKeys->registerTemporalAuthCode($code);

        $request = $this->makeRequest('POST', '/oauth/openid/tenant1/token', [
            'grant_type' => 'authorization_code',
            'code' => $codeKey,
            'client_id' => self::CLIENT_ID,
            'redirect_uri' => 'https://app.example.com/callback',
            'client_secret' => self::CLIENT_SECRET,
        ]);

        $response = $this->controller->post($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(200, $response->getStatusCode());
        $body = $this->decodeJson($response);
        $this->assertArrayHasKey('access_token', $body);
        $this->assertArrayHasKey('id_token', $body);
        $this->assertArrayHasKey('refresh_token', $body);
        $this->assertSame('Bearer', $body['token_type']);
    }

