    public function testAuthorizationCodeWithPkceS256(): void
    {
        $verifier = bin2hex(random_bytes(32));
        $challenge = rtrim(strtr(base64_encode(hash('sha256', $verifier, true)), '+/', '-_'), '=');

        $clientData = $this->clientStore->preValidatedClient(self::CLIENT_ID);
        $authResult = new AuthenticationResult(
            valid: true,
            id: self::USER_ID,
            tenant: self::TENANT,
            tenantName: self::TENANT,
            scope: 'openid',
        );
        $authRequest = new AuthenticationRequest($clientData, 'openid', 'https://app.example.com/callback');
        $code = new TemporalAuthCode(
            data: $authResult,
            client: $clientData,
            nonce: 'nonce-pkce',
            request: $authRequest,
            codeChallenge: $challenge,
            codeChallengeMethod: 'S256',
        );
        $codeKey = $this->temporalKeys->registerTemporalAuthCode($code);

        $request = $this->makeRequest('POST', '/oauth/openid/tenant1/token', [
            'grant_type' => 'authorization_code',
            'code' => $codeKey,
            'code_verifier' => $verifier,
            'client_id' => self::CLIENT_ID,
            'redirect_uri' => 'https://app.example.com/callback',
            'client_secret' => self::CLIENT_SECRET,
        ]);

        $response = $this->controller->post($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(200, $response->getStatusCode());
        $body = $this->decodeJson($response);
        $this->assertArrayHasKey('access_token', $body);
    }

    public function testAuthorizationCodeWithPkceMissingVerifierReturns400(): void
    {
        $challenge = rtrim(strtr(base64_encode(hash('sha256', 'some-verifier', true)), '+/', '-_'), '=');

        $clientData = $this->clientStore->preValidatedClient(self::CLIENT_ID);
        $authResult = new AuthenticationResult(valid: true, id: self::USER_ID, tenant: self::TENANT, tenantName: self::TENANT, scope: 'openid');
        $authRequest = new AuthenticationRequest($clientData, 'openid', 'https://app.example.com/callback');
        $code = new TemporalAuthCode(
            data: $authResult,
            client: $clientData,
            nonce: 'nonce',
            request: $authRequest,
            codeChallenge: $challenge,
            codeChallengeMethod: 'S256',
        );
        $codeKey = $this->temporalKeys->registerTemporalAuthCode($code);

        $request = $this->makeRequest('POST', '/oauth/openid/tenant1/token', [
            'grant_type' => 'authorization_code',
            'code' => $codeKey,
            'client_id' => self::CLIENT_ID,
            'redirect_uri' => 'https://app.example.com/callback',
            'client_secret' => self::CLIENT_SECRET,
        ]);

        $response = $this->controller->post($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(400, $response->getStatusCode());
        $body = $this->decodeJson($response);
        $this->assertSame('invalid_request', $body['error']);

        $retry = $request->withParsedBody([...$request->getParsedBody(), 'code_verifier' => 'some-verifier']);
        $this->assertSame(200, $this->controller->post($retry, new Response(200), ['tenant' => self::TENANT])->getStatusCode());
    }

