        $refreshToken = $this->redeemCodeWithAudience(self::CLIENT_ID)['refresh_token'];

        $this->assertSame(302, $this->logout('other-session')->getStatusCode());

        $this->assertSame(200, $this->refreshStatus($refreshToken));
    }

